import React, { useState } from "react";
import "./App.css";
import Navbar from "./components/Navbar";
import ChatBox from "./components/ChatBox";

const App = () => {
  const [activePage, setActivePage] = useState("chat");

  return (
    <div className="app-container">
      <Navbar setActivePage={setActivePage} />

      <div className="content">
        {activePage === "chat" && <ChatBox />}

        {activePage === "youtube" && (
          <div className="youtube">
            <h2>📺 YouTube Learning</h2>
            <p>Watch AI-related YouTube videos here!</p>
          </div>
        )}

        {activePage === "wikipedia" && (
          <div className="wikipedia">
            <h2>📖 Wikipedia Search</h2>
            <p>Look up AI-related articles on Wikipedia.</p>
          </div>
        )}

        {activePage === "test" && (
          <div className="test">
            <h2>📝 AI Knowledge Test</h2>
            <p>Take quizzes and tests to check your understanding.</p>
          </div>
        )}
      </div>

      <footer className="footer">
        <p>&copy; 2025 PAT | @Indrajit002</p>
      </footer>
    </div>
  );
};

export default App;
